from lib import *
S = SS('u145')
steps = [
    step("Command 不经过 shell:Command::new(\"echo\").arg(\"hello\").arg(\"a; echo INJECTED\").arg(\"$HOME\") 输出 \"hello a; echo INJECTED $HOME\\n\" —— 分号和 $HOME 都是原样字符,没有被解释,也就没有注入;output() 一次性收集结果:状态码 Some(0)、success() = true。sh -c \"echo out; echo err 1>&2; exit 3\" 得到 stdout \"out\\n\"、stderr \"err\\n\"、退出码 Some(3)、success() = false。", t=tl(S(1)), done=lidx(S(1), 'echo 输出', '参数里的', 'sh -c'), kv=KV([['arg(\"a; …\")', '字面量,不经过 shell'], ['output()', 'stdout + stderr + status']], ['arg(\"a; …\")'])),
    step("错误:不存在的命令 → NotFound(os error 2);文件没有执行权限 → PermissionDenied(os error 13);子进程被 SIGTERM 终止时 code() 是 None,signal() 是 Some(15),success() = false,Display 写作「signal: 15 (SIGTERM)」。区分「退出码非 0」和「被信号终止」要看 code() 是否为 None。", t=tl(S(2)), done=lidx(S(2), '不存在的命令', '没有执行权限', '子进程被 SIGTERM', 'Display'), kv=KV([['不存在', 'NotFound / 2'], ['无权限', 'PermissionDenied / 13'], ['被信号终止', 'code() = None,signal() = Some(15)']], ['被信号终止'])),
    step("管道:spawn 一个 sort -r,stdin(Stdio::piped())写入三行再 drop 掉 stdin(这样子进程读到 EOF),wait_with_output 得到 \"cherry\\nbanana\\napple\\n\";把前一个进程的 stdout 接到后一个的 stdin:printf | wc -l 得到 3。", t=tl(S(3)), done=lidx(S(3), 'sort -r', '管道 printf'), kv=KV([['stdin 写完要 drop', '子进程才能读到 EOF'], ['Stdio::from(child.stdout)', '连接两个进程']], ['stdin 写完要 drop'])),
    step("经典死锁:子进程先往 stderr 写 200000 字节,再往 stdout 写 \"done\";父进程先读 stdout。500 ms 后读 stdout 的线程仍未完成(false)—— 子进程卡在写满的 stderr 管道上,既不能退出也不能关闭 stdout,父进程又在等 stdout 的 EOF,互相等待。开始读 stderr 后立刻解除(读到 200000 字节,只用 3 ms),stdout 线程得到 \"done\"。output() 内部同时读两个管道,不会死锁。", t=tl(S(4)), mark=lidx(S(4), '500 ms 后'), done=lidx(S(4), '现在读 stderr', 'stdout 线程结果', '对照'), kv=KV([['只读一个管道', '另一个写满 → 死锁'], ['output() / wait_with_output()', '同时读两个']], ['只读一个管道'])),
    step("环境变量与工作目录:子进程默认继承父进程环境;env(\"MY\", …) 加变量、current_dir(\"/tmp\") 改工作目录(PWD 的 basename 变成 tmp);env_clear() 之后连 HOME 都没有了(HOME_SET 为空),只剩手动设置的 MY=only;env_remove(\"HOME\") 只去掉一个。", t=tl(S(5)), done=lidx(S(5), '继承环境', 'env_clear', 'env_remove'), kv=KV([['默认', '继承全部环境'], ['env_clear', '一个都不继承'], ['env_remove', '去掉指定的']], ['env_clear'])),
    step("不 wait 的子进程会变成僵尸:子进程 true 已经退出,父进程没有 wait,ps 状态是 Z(僵尸);drop(Child) 之后仍是 Z —— drop 不会回收子进程;调用 wait() 之后拿到退出状态 Some(0),ps 里这个 pid 消失了(已被回收)。长期运行的程序 spawn 之后必须 wait(或交给一个线程 wait)。", t=tl(S(6)), mark=lidx(S(6), '"Z"'), done=lidx(S(6), '调用 wait() 之后'), kv=KV([['没 wait', '僵尸 Z,drop 也不回收'], ['wait()', '回收,拿到退出状态']], ['没 wait'])),
]
A = mkart('u145', 145, 'Rust,子进程,Command,管道,真实验证,动画演示',
    '用 std::process::Command 与真实命令验证子进程:参数不经 shell(没有注入);output 收集 stdout/stderr/退出码;NotFound(2)/PermissionDenied(13);被信号终止时 code() 为 None;管道与 wait_with_output;只读一个管道造成的死锁;env/env_clear/current_dir;不 wait 的子进程成为僵尸(Z)。',
    'Command 看起来很简单,实际有不少陷阱:参数会不会被 shell 解释?退出码与信号怎么区分?管道读法不对为什么死锁?子进程什么时候变僵尸?这篇每个问题都跑一个真实的子进程来回答。',
    [('0 次注入', '含 ; 与 $HOME 的参数被 shell 解释的次数(参数不经过 shell)'), ('None', '子进程被信号终止时 ExitStatus::code() 的值'), ('Z', '没有 wait 的已退出子进程在 ps 里的状态(僵尸)')],
    [('output 与参数', '<p>信号的细节见<a href="rust-signal-handling.html">信号处理</a>;标准输入输出重定向见<a href="rust-stdio-redirect.html">标准输入输出重定向</a>。</p>'), ('错误与退出状态', None), ('管道', None), ('管道死锁', '<p>死锁是 macOS 上的实测现象;管道缓冲区的具体大小没有测量。</p>'), ('环境与工作目录', '<p>环境变量读取见<a href="rust-env-vars.html">环境变量读取</a>。</p>'), ('僵尸进程', None)],
    steps, [ENV_U + '。sort、wc、printf、sh 为系统自带', '没有验证:Windows 上的 Command(参数拼接成命令行字符串的转义规则)、Stdio::inherit 的行为、process_group 与 setsid、kill 一个进程树、tokio::process、exec 替换当前进程(CommandExt::exec)'], '子进程与 Command')
